def validar_datos_previos(apps, schema_editor):
    Cotizacion = apps.get_model('cotizaciones', 'CotizacionProveedor')
    qs = Cotizacion.objects.using(schema_editor.connection.alias)
    repetidos = list(qs.filter(estado='GANADORA').values('item_id').annotate(n=Count('id')).filter(n__gt=1).values_list('item_id', flat=True)[:10])
    if repetidos:
        raise RuntimeError('Hay varias cotizaciones ganadoras para los ítems %s. Revisa la selección existente antes de migrar.' % repetidos)
    if qs.filter(precio__lt=0).exists():
        raise RuntimeError('Hay cotizaciones con costo negativo. Corrígelas antes de migrar.')


